.input-warning {
  display: none;

  input:user-invalid ~ &,
  input[aria-invalid="true"] ~ & {
    display: inline-block;
  }
}

.input-success {
  display: none;

  /* Optional fields need to have placeholder="" or an actual placeholder so the
   * validity checkmark doesn't show in their empty state. If we ever get the
   * :blank pseudo class, we can use that instead. */
  input:user-valid:not(:optional:placeholder-shown) ~ &,
  input:valid:not(:placeholder-shown) ~ & {
    display: inline-block;
  }
}

